// n8n Code node — Mode: "Run Once for All Items"
// This branches OFF the same Postgres node output, in parallel with the
// regional formatter — same 5 region-grouped items go into both.

const regions = $input.all().map(item => item.json);

const totalOrders = regions.reduce((sum, r) => sum + r.products.length, 0); // product-lines, not raw order count
const totalQuantity = regions.reduce((sum, r) => sum + r.region_total_quantity, 0);
const totalValue = regions.reduce((sum, r) => sum + r.region_total_value, 0);

// Rank regions by value, descending
const rankedRegions = [...regions].sort((a, b) => b.region_total_value - a.region_total_value);

const regionLines = rankedRegions.map((r, i) =>
  `${i + 1}️⃣ ${r.region_name}\n   ₹${r.region_total_value.toLocaleString('en-IN')} | ${r.region_total_quantity} units`
);

// Aggregate product totals across ALL regions
const productTotals = {};
regions.forEach(r => {
  r.products.forEach(p => {
    if (!productTotals[p.product_name]) {
      productTotals[p.product_name] = { quantity: 0, value: 0 };
    }
    productTotals[p.product_name].quantity += p.quantity;
    productTotals[p.product_name].value += p.value;
  });
});

const topProducts = Object.entries(productTotals)
  .sort((a, b) => b[1].value - a[1].value)
  .slice(0, 5)
  .map(([name, totals]) => `• ${name} — ${totals.quantity} units`);

const today = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });

const summary =
`📊 DAILY DAIRY BUSINESS SUMMARY
📅 ${today}

━━━━━━━━━━━━━━━━━━
💰 TOTAL BUSINESS VALUE
₹${totalValue.toLocaleString('en-IN')}

📦 TOTAL UNITS
${totalQuantity}

━━━━━━━━━━━━━━━━━━
📍 REGION PERFORMANCE

${regionLines.join('\n\n')}

━━━━━━━━━━━━━━━━━━
🏆 TOP PRODUCTS

${topProducts.join('\n')}`;

return [{
  json: {
    message: summary,
    total_value: totalValue,
    total_quantity: totalQuantity,
    region_count: regions.length
  }
}];

// n8n Code node — runs once per input item (region).
// Mode: "Run Once for Each Item"
// Adds a header row + separator line above the product table.

const region = $input.item.json;

const productEmoji = {
  "Full Cream Milk": "🥛", "Toned Milk": "🥛", "Curd": "🥣", "Sweet Curd": "🥣",
  "Buttermilk": "🧃", "Paneer": "🧀", "Cottage Cheese Cubes": "🧀",
  "Ghee": "🫙", "Butter": "🧈", "Lassi": "🥤", "Flavoured Milkshake": "🥤",
  "Khova": "🍬"
};

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const NAME_WIDTH = 24;
const QTY_WIDTH = 5;
const VALUE_WIDTH = 10;
const TOTAL_WIDTH = NAME_WIDTH + QTY_WIDTH + VALUE_WIDTH;

const header = "Product".padEnd(NAME_WIDTH) + "Qty".padStart(QTY_WIDTH) + "Value".padStart(VALUE_WIDTH);
const separator = "-".repeat(TOTAL_WIDTH);

const tableLines = region.products.map(p => {
  const emoji = productEmoji[p.product_name] || "•";
  const name = (emoji + " " + p.product_name).padEnd(NAME_WIDTH, " ");
  const qty = String(p.quantity).padStart(QTY_WIDTH);
  const value = ("₹" + p.value.toLocaleString('en-IN')).padStart(VALUE_WIDTH);
  return `${name}${qty}${value}`;
});

const fullTable = [header, separator, ...tableLines].join('\n');

const today = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });

const message =
`🥛 <b>DAILY ORDER SUMMARY — ${escapeHtml(region.region_name.toUpperCase())}</b>
📅 ${today}

<pre>${escapeHtml(fullTable)}</pre>

📦 Total Quantity: <b>${region.region_total_quantity} units</b>
💰 Total Value: <b>₹${region.region_total_value.toLocaleString('en-IN')}</b>`;

return {
  json: {
    region_id: region.region_id,
    region_name: region.region_name,
    telegram_chat_id: region.telegram_chat_id,
    whatsapp_group_id: region.whatsapp_group_id,
    message: message,
    region_total_quantity: region.region_total_quantity,
    region_total_value: region.region_total_value
  }
};
